source /home/stsrjkt/kakomon-generator/.env && npx tsx -e "
import { createClient } from '@supabase/supabase-js';
const sb = createClient(process.env.SUPABASE_URL!, process.env.SUPABASE_SERVICE_ROLE_KEY!);
const { data } = await sb.from('kakomon_universities').select('id, name, slug').order('slug');
// 中国地方の大学をフィルタ
const chugoku = ['広島','岡山','島根','鳥取','山口'];
const filtered = data?.filter(u => chugoku.some(p => u.name.includes(p))) || [];
filtered.forEach(u => console.log(u.id + '\t' + u.slug + '\t' + u.name));
console.log('---');
console.log('Total:', filtered.length);
" 2>/dev/null

