  credentials: { accessKeyId: process.env.R2_ACCESS_KEY_ID, secretAccessKey: process.env.R2_SECRET_ACCESS_KEY }
});
const keys = [
  \"tottori/2023/math/zenki/answer.pdf\",
  \"tottori/2023/math/zenki/problem.pdf\",
  \"tottori/2024/math/zenki/answer.pdf\",
  \"tottori/2024/math/zenki/problem.pdf\",
  \"tottori/2025/math/zenki/answer.pdf\",
  \"tottori/2025/math/zenki/problem.pdf\"
];
for (const key of keys) {
  await client.send(new DeleteObjectCommand({ Bucket: process.env.R2_BUCKET_NAME, Key: key }));
  console.log(\"Deleted R2:\", key);
