"'

# Shimane: Copy R2 objects to new paths, then update DB, then delete old
# 1. sorigo_other → sorigo_zaiene (2022, 2 files)
# 2. med_suuri → med (2022 2 files + 2024 2 files = 4 files)
bash -lc 'set -a; source /home/stsrjkt/kakomon-generator/.env; set +a; node --input-type=module -e "
import { S3Client, CopyObjectCommand, DeleteObjectCommand } from \"@aws-sdk/client-s3\";
const client = new S3Client({
  region: \"auto\",
  endpoint: \"https://\" + process.env.R2_ACCOUNT_ID + \".r2.cloudflarestorage.com\",
  credentials: { accessKeyId: process.env.R2_ACCESS_KEY_ID, secretAccessKey: process.env.R2_SECRET_ACCESS_KEY }
});
const Bucket = process.env.R2_BUCKET_NAME;
const renames = [
  // sorigo_other → sorigo_zaiene (2022)
  [\"shimane/2022/math_sorigo_other/zenki/answer.pdf\", \"shimane/2022/math_sorigo_zaiene/zenki/answer.pdf\"],
  [\"shimane/2022/math_sorigo_other/zenki/problem.pdf\", \"shimane/2022/math_sorigo_zaiene/zenki/problem.pdf\"],
  // med_suuri → med (2022)
  [\"shimane/2022/math_med_suuri/zenki/answer.pdf\", \"shimane/2022/math_med/zenki/answer.pdf\"],
  [\"shimane/2022/math_med_suuri/zenki/problem.pdf\", \"shimane/2022/math_med/zenki/problem.pdf\"],
  // med_suuri → med (2024)
  [\"shimane/2024/math_med_suuri/zenki/answer.pdf\", \"shimane/2024/math_med/zenki/answer.pdf\"],
  [\"shimane/2024/math_med_suuri/zenki/problem.pdf\", \"shimane/2024/math_med/zenki/problem.pdf\"],
];
for (const [from, to] of renames) {
  await client.send(new CopyObjectCommand({ Bucket, CopySource: Bucket + \"/\" + from, Key: to }));
  console.log(\"Copied:\", from, \"→\", to);
}
console.log(\"All copies done. Now deleting old keys...\");
for (const [from] of renames) {
  await client.send(new DeleteObjectCommand({ Bucket, Key: from }));
  console.log(\"Deleted:\", from);
}
console.log(\"R2 rename complete.\");
"'

