 1→#!/usr/bin/env tsx
 2→/**
 3→ * Ingest "add" fixes (download official PDFs -> upload to R2 -> upsert kakomon_documents).
 4→ *
 5→ * This is a deterministic alternative to kakomon-collector for this repo.
 6→ *
 7→ * Usage:
 8→ *   bash -lc 'set -a; source .env; set +a; npx -y tsx@4.19.0 scripts/ingest-add-by-fixes.ts --add-fixes path/to/fixes-add.json --dry-run'
 9→ *   bash -lc 'set -a; source .env; set +a; npx -y tsx@4.19.0 scripts/ingest-add-by-fixes.ts --add-fixes path/to/fixes-add.json --force'
10→ */
11→
12→import { readFileSync, mkdtempSync, rmSync } from "fs";
13→import { tmpdir } from "os";
14→import path from "path";
15→import { spawnSync } from "child_process";
16→import net from "net";
17→import { createClient } from "@supabase/supabase-js";
18→import { uploadToR2 } from "../src/lib/r2";
19→import { normalizeSubject } from "../src/lib/normalize-subject";
20→
21→type FixEntry = {
22→  url: string;
23→  university_id: string;
24→  year: number;
25→  subject_id: string;
26→  subject_variant: string | null;
27→  subject_raw: string;
28→  subject_display: string;
29→  exam_type: string;
30→  exam_variant: string | null;
31→  exam_type_raw: string;
32→  content_type: "problem" | "answer";
33→  is_bundled: boolean;
34→  bundled_subjects: string[] | null;
35→  action: "add" | "split";
36→  r2_path: string;
37→};
38→
39→function getArg(name: string): string | null {
40→  const idx = process.argv.indexOf(name);
41→  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
42→  return null;
43→}
44→
45→function isPrivateOrLocalhost(hostname: string): boolean {
46→  const h = hostname.toLowerCase();
47→  if (h === "localhost" || h.endsWith(".localhost") || h.endsWith(".local")) return true;
