  1→import { createClient, type SupabaseClient } from "@supabase/supabase-js";
  2→import type { ExamType } from "../types.js";
  3→import { normalizeSubject } from "./normalize-subject.js";
  4→
  5→let supabaseClient: SupabaseClient | null = null;
  6→
  7→function getSupabaseClient(): SupabaseClient {
  8→  if (supabaseClient) return supabaseClient;
  9→
 10→  const url = process.env.SUPABASE_URL;
 11→  const key = process.env.SUPABASE_SERVICE_ROLE_KEY;
 12→  if (!url || !key) {
 13→    throw new Error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
 14→  }
 15→  supabaseClient = createClient(url, key);
 16→  return supabaseClient;
 17→}
 18→
 19→/**
 20→ * 大学をIDまたは名前で検索し、IDを返す（存在しない場合は自動的にinsert）
 21→ * CLIからは "iwate" のようなIDが渡されることも、"岩手大学" のような名前が渡されることもある
 22→ */
 23→export async function upsertUniversity(name: string): Promise<string> {
 24→  const supabase = getSupabaseClient();
 25→
 26→  // まずIDとして検索
 27→  const { data: byId } = await supabase
 28→    .from("kakomon_universities")
 29→    .select("id")
 30→    .eq("id", name)
 31→    .maybeSingle();
 32→
 33→  if (byId) return byId.id as string;
 34→
 35→  // 次にnameとして検索
 36→  const { data: byName } = await supabase
 37→    .from("kakomon_universities")
 38→    .select("id")
 39→    .eq("name", name)
 40→    .maybeSingle();
 41→
 42→  if (byName) return byName.id as string;
 43→
 44→  // 見つからなければ新規作成（idとnameの両方にnameを使用）
 45→  const { data, error } = await supabase
 46→    .from("kakomon_universities")
 47→    .insert({ id: name, name })
 48→    .select("id")
 49→    .single();
 50→
 51→  if (error) throw new Error(`Failed to create university "${name}": ${error.message}`);
 52→  if (!data) throw new Error(`Failed to create university "${name}": no data returned`);
 53→  console.log(`  DB: 大学を新規登録 "${name}" → ${data.id}`);
 54→  return data.id as string;
 55→}
 56→
 57→const isForceMode = process.argv.includes("--force");
 58→
 59→async function deleteDocumentCascade(documentId: string): Promise<void> {
 60→  const supabase = getSupabaseClient();
 61→  await supabase
 62→    .from("kakomon_questions")
 63→    .delete()
 64→    .eq("document_id", documentId);
 65→  await supabase
 66→    .from("kakomon_documents")
 67→    .delete()
 68→    .eq("id", documentId);
 69→}
 70→
 71→/**
 72→ * ドキュメント（問題 or 解答）レコードを作成し、IDを返す
 73→ * 既存レコードがある場合:
 74→ *   --force なし → エラーで停止
 75→ *   --force あり → 関連クエスチョンを削除してからドキュメントを削除し、新規登録
 76→ */
 77→export async function createDocument(params: {
 78→  universityId: string;
 79→  year: number;
 80→  subject: string;
 81→  examType: ExamType;
 82→  contentType: "problem" | "answer";
 83→  pdfStoragePath: string;
 84→  subjectVariant?: string | null;
 85→}): Promise<string> {
 86→  const supabase = getSupabaseClient();
 87→
 88→  // 既存レコードの確認（従来キー）
 89→  const { data: existingByComposite } = await supabase
 90→    .from("kakomon_documents")
 91→    .select("id")
 92→    .eq("university_id", params.universityId)
 93→    .eq("year", params.year)
 94→    .eq("subject", params.subject)
 95→    .eq("exam_type", params.examType)
 96→    .eq("content_type", params.contentType)
 97→    .maybeSingle();
 98→
 99→  // pdf_storage_path の一意制約に対する既存レコード確認（科目表記揺れ等の取りこぼし対策）
100→  const { data: existingByPath } = await supabase
101→    .from("kakomon_documents")
102→    .select("id")
103→    .eq("pdf_storage_path", params.pdfStoragePath)
104→    .maybeSingle();
105→
106→  const existingIds = new Set<string>();
107→  if (existingByComposite?.id) existingIds.add(existingByComposite.id as string);
108→  if (existingByPath?.id) existingIds.add(existingByPath.id as string);
109→
110→  if (existingIds.size > 0) {
111→    if (!isForceMode) {
112→      throw new Error(
113→        `既に登録済みです (${params.universityId}/${params.year}/${params.subject}/${params.examType}/${params.contentType})。上書きするには --force を付けてください`,
114→      );
115→    }
116→    // --force: 関連クエスチョンを削除してからドキュメントを削除
117→    for (const id of existingIds) {
118→      await deleteDocumentCascade(id);
119→      console.log(`  DB: 既存データを削除 (${params.contentType}: ${id})`);
120→    }
