#!/usr/bin/env tsx
/**
 * Query kakomon_documents with filters and display results.
 *
 * Usage:
 *   npx tsx scripts/query-documents.ts --university shimane --subject math
 *   npx tsx scripts/query-documents.ts --university shimane --subject math --year 2024
 *   npx tsx scripts/query-documents.ts --university shimane --subject math --variants
 *   npx tsx scripts/query-documents.ts --university shimane --subject math --compact
 */

import { createClient } from "@supabase/supabase-js";

function getArg(name: string): string | null {
  const idx = process.argv.indexOf(name);
  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
  return null;
}

const university = getArg("--university");
const subject = getArg("--subject");
const year = getArg("--year");
const showVariants = process.argv.includes("--variants");
const compact = process.argv.includes("--compact");

if (!university) {
  console.error("Usage: npx tsx scripts/query-documents.ts --university <id> [--subject <en>] [--year <n>] [--variants] [--compact]");
  process.exit(1);
}

const sbUrl = process.env.SUPABASE_URL;
const sbKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!sbUrl || !sbKey) {
  console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
  process.exit(1);
}
const supabase = createClient(sbUrl, sbKey);

async function main() {
  let query = supabase
    .from("kakomon_documents")
    .select("id,year,subject,subject_variant,exam_type,content_type,pdf_storage_path")
    .eq("university_id", university!)
    .order("year")
    .order("exam_type")
    .order("subject_variant")
    .order("content_type");

  if (subject) query = query.eq("subject", subject);
  if (year) query = query.eq("year", parseInt(year));

  const { data, error } = await query;
  if (error) { console.error(error); process.exit(1); }
  if (!data || data.length === 0) {
    console.log("No records found.");
    return;
  }

  // --variants mode: just show unique variants
  if (showVariants) {
    const variants = [...new Set(data.map((r: any) => r.subject_variant))];
    console.log(`Variants for ${university}/${subject ?? "all"}:`);
    for (const v of variants) console.log(`  ${v ?? "(null)"}`);
    console.log(`Total: ${variants.length}`);
    return;
  }

  // --compact mode: one-line per record
  if (compact) {
    for (const r of data) {
      console.log(`${r.year} ${r.exam_type.padEnd(6)} ${(r.subject_variant ?? "-").padEnd(20)} ${r.content_type.padEnd(8)} ${r.pdf_storage_path}`);
    }
    console.log(`--- Total: ${data.length} records`);
    return;
  }

  // Default: grouped by year
  const byYear = new Map<number, any[]>();
  for (const r of data) {
    const arr = byYear.get(r.year) ?? [];
    arr.push(r);
    byYear.set(r.year, arr);
  }

  for (const [yr, records] of byYear) {
    console.log(`\n=== ${yr} ===`);
    for (const r of records) {
      const sv = r.subject_variant ? `[${r.subject_variant}]` : "";
      console.log(`  ${r.exam_type.padEnd(6)} ${sv.padEnd(22)} ${r.content_type.padEnd(8)} ${r.pdf_storage_path}`);
    }
  }
  console.log(`\nTotal: ${data.length} records`);
}

main().catch((err) => { console.error(err); process.exit(1); });

