#!/usr/bin/env tsx
/**
 * Rename subject_variant for kakomon_documents (DB + R2 paths).
 *
 * Steps:
 *   1. Find matching DB records
 *   2. Copy R2 objects to new paths
 *   3. Update DB (subject_variant + pdf_storage_path)
 *   4. Delete old R2 objects
 *
 * Usage:
 *   npx tsx scripts/rename-variant.ts --university shimane --subject math --from med_suuri --to med --dry-run
 *   npx tsx scripts/rename-variant.ts --university shimane --subject math --from med_suuri --to med --force
 *   npx tsx scripts/rename-variant.ts --university shimane --subject math --from sorigo_other --to sorigo_zaiene --year 2022 --force
 */

import { createClient } from "@supabase/supabase-js";
import {
  S3Client,
  CopyObjectCommand,
  DeleteObjectCommand,
  HeadObjectCommand,
} from "@aws-sdk/client-s3";

function getArg(name: string): string | null {
  const idx = process.argv.indexOf(name);
  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
  return null;
}

const university = getArg("--university");
const subject = getArg("--subject");
const fromVariant = getArg("--from");
const toVariant = getArg("--to");
const yearFilter = getArg("--year");
const dryRun = process.argv.includes("--dry-run");
const force = process.argv.includes("--force");

if (!university || !subject || !fromVariant || !toVariant) {
  console.error("Usage: npx tsx scripts/rename-variant.ts --university <id> --subject <en> --from <old> --to <new> [--year <n>] [--dry-run | --force]");
  process.exit(1);
}
if (!dryRun && !force) {
  console.error("Specify --dry-run or --force");
  process.exit(1);
}

const sbUrl = process.env.SUPABASE_URL;
const sbKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!sbUrl || !sbKey) {
  console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
  process.exit(1);
}
const supabase = createClient(sbUrl, sbKey);

const accountId = process.env.R2_ACCOUNT_ID;
const accessKeyId = process.env.R2_ACCESS_KEY_ID;
const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
const bucketName = process.env.R2_BUCKET_NAME ?? "kakomon";
if (!accountId || !accessKeyId || !secretAccessKey) {
  console.error("R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY are required");
  process.exit(1);
}
const r2 = new S3Client({
  region: "auto",
  endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
  credentials: { accessKeyId, secretAccessKey },
});

function computeNewPath(oldPath: string, from: string, to: string): string {
  // Replace the variant portion in the path: math_med_suuri/ → math_med/
  const oldSegment = `${subject}_${from}/`;
  const newSegment = `${subject}_${to}/`;
  if (oldPath.includes(oldSegment)) {
    return oldPath.replace(oldSegment, newSegment);
  }
  // Fallback: shouldn't happen if data is consistent
  console.warn(`  WARNING: path does not contain expected segment "${oldSegment}": ${oldPath}`);
  return oldPath;
}

async function main() {
  console.log(`Mode: ${dryRun ? "DRY RUN" : "LIVE"}`);
  console.log(`Rename: ${university}/${subject} variant "${fromVariant}" → "${toVariant}"${yearFilter ? ` (year=${yearFilter})` : ""}\n`);

  // 1. Find matching records
  let query = supabase
    .from("kakomon_documents")
    .select("id,year,subject_variant,exam_type,content_type,pdf_storage_path")
    .eq("university_id", university!)
    .eq("subject", subject!)
    .eq("subject_variant", fromVariant!)
    .order("year")
    .order("content_type");

  if (yearFilter) query = query.eq("year", parseInt(yearFilter));

  const { data, error } = await query;
  if (error) { console.error(error); process.exit(1); }
  if (!data || data.length === 0) {
    console.log("No matching records found.");
    return;
  }

  console.log(`Found ${data.length} records:\n`);

  // 2. Compute renames
  const ops: { id: string; oldPath: string; newPath: string; year: number; ct: string }[] = [];
  for (const r of data) {
    const newPath = computeNewPath(r.pdf_storage_path, fromVariant!, toVariant!);
    ops.push({ id: r.id, oldPath: r.pdf_storage_path, newPath, year: r.year, ct: r.content_type });
    console.log(`  ${r.year} ${r.content_type.padEnd(8)} ${r.pdf_storage_path}`);
    console.log(`  ${"".padEnd(14)} → ${newPath}`);
  }

  if (dryRun) {
    console.log("\n(dry-run: no changes made)");
    return;
  }

  // 3. R2 copy
  console.log("\nCopying R2 objects...");
  for (const op of ops) {
    await r2.send(new CopyObjectCommand({
      Bucket: bucketName,
      CopySource: `${bucketName}/${op.oldPath}`,
      Key: op.newPath,
    }));
    console.log(`  Copied: ${op.oldPath} → ${op.newPath}`);
  }

  // 4. DB update
  console.log("\nUpdating DB...");
  for (const op of ops) {
    const { error: ue } = await supabase
      .from("kakomon_documents")
      .update({ subject_variant: toVariant, pdf_storage_path: op.newPath })
      .eq("id", op.id);
    if (ue) {
      console.error(`  FAILED DB update ${op.id}: ${ue.message}`);
    } else {
      console.log(`  Updated: ${op.id.slice(0, 8)} → variant=${toVariant}, path=${op.newPath}`);
    }
  }

  // 5. R2 delete old
  console.log("\nDeleting old R2 objects...");
  for (const op of ops) {
    await r2.send(new DeleteObjectCommand({ Bucket: bucketName, Key: op.oldPath }));
    console.log(`  Deleted: ${op.oldPath}`);
  }

  // 6. Verify
  console.log("\nVerifying new R2 objects...");
  let okCount = 0;
  for (const op of ops) {
    try {
      await r2.send(new HeadObjectCommand({ Bucket: bucketName, Key: op.newPath }));
      okCount++;
    } catch {
      console.error(`  MISSING: ${op.newPath}`);
    }
  }
  console.log(`\nDone: ${okCount}/${ops.length} verified.`);
}

main().catch((err) => { console.error(err); process.exit(1); });

