  // Replace the variant portion in the path: math_med_suuri/ → math_med/
  const oldSegment = `${subject}_${from}/`;
  const newSegment = `${subject}_${to}/`;
  if (oldPath.includes(oldSegment)) {
    return oldPath.replace(oldSegment, newSegment);
  }
  // Fallback: shouldn't happen if data is consistent
  console.warn(`  WARNING: path does not contain expected segment "${oldSegment}": ${oldPath}`);
  return oldPath;
}

async function main() {
  console.log(`Mode: ${dryRun ? "DRY RUN" : "LIVE"}`);
  console.log(`Rename: ${university}/${subject} variant "${fromVariant}" → "${toVariant}"${yearFilter ? ` (year=${yearFilter})` : ""}\n`);

  // 1. Find matching records
  let query = supabase
    .from("kakomon_documents")
    .select("id,year,subject_variant,exam_type,content_type,pdf_storage_path")
    .eq("university_id", university!)
    .eq("subject", subject!)
    .eq("subject_variant", fromVariant!)
    .order("year")
    .order("content_type");

  if (yearFilter) query = query.eq("year", parseInt(yearFilter));

  const { data, error } = await query;
  if (error) { console.error(error); process.exit(1); }
  if (!data || data.length === 0) {
    console.log("No matching records found.");
    return;
  }

  console.log(`Found ${data.length} records:\n`);

  // 2. Compute renames
  const ops: { id: string; oldPath: string; newPath: string; year: number; ct: string }[] = [];
  for (const r of data) {
    const newPath = computeNewPath(r.pdf_storage_path, fromVariant!, toVariant!);
    ops.push({ id: r.id, oldPath: r.pdf_storage_path, newPath, year: r.year, ct: r.content_type });
    console.log(`  ${r.year} ${r.content_type.padEnd(8)} ${r.pdf_storage_path}`);
    console.log(`  ${"".padEnd(14)} → ${newPath}`);
  }

  if (dryRun) {
    console.log("\n(dry-run: no changes made)");
    return;
  }

  // 3. R2 copy
  console.log("\nCopying R2 objects...");
  for (const op of ops) {
    await r2.send(new CopyObjectCommand({
      Bucket: bucketName,
      CopySource: `${bucketName}/${op.oldPath}`,
      Key: op.newPath,
    }));
    console.log(`  Copied: ${op.oldPath} → ${op.newPath}`);
  }

  // 4. DB update
  console.log("\nUpdating DB...");
  for (const op of ops) {
    const { error: ue } = await supabase
      .from("kakomon_documents")
      .update({ subject_variant: toVariant, pdf_storage_path: op.newPath })
      .eq("id", op.id);
    if (ue) {
      console.error(`  FAILED DB update ${op.id}: ${ue.message}`);
    } else {
      console.log(`  Updated: ${op.id.slice(0, 8)} → variant=${toVariant}, path=${op.newPath}`);
    }
  }

  // 5. R2 delete old
  console.log("\nDeleting old R2 objects...");
  for (const op of ops) {
    await r2.send(new DeleteObjectCommand({ Bucket: bucketName, Key: op.oldPath }));
    console.log(`  Deleted: ${op.oldPath}`);
  }

  // 6. Verify
  console.log("\nVerifying new R2 objects...");
  let okCount = 0;
  for (const op of ops) {
    try {
      await r2.send(new HeadObjectCommand({ Bucket: bucketName, Key: op.newPath }));
      okCount++;
    } catch {
      console.error(`  MISSING: ${op.newPath}`);
    }
  }
  console.log(`\nDone: ${okCount}/${ops.length} verified.`);
}

main().catch((err) => { console.error(err); process.exit(1); });

