#!/usr/bin/env tsx
/**
 * Delete kakomon_documents by ID (DB + R2).
 * Checks for linked kakomon_questions and refuses to delete if any exist (unless --cascade).
 *
 * Usage:
 *   npx tsx scripts/delete-documents.ts --ids "id1,id2,id3" --dry-run
 *   npx tsx scripts/delete-documents.ts --ids "id1,id2,id3" --force
 *   npx tsx scripts/delete-documents.ts --ids "id1,id2,id3" --force --cascade
 *
 * Or filter-based (no --ids needed):
 *   npx tsx scripts/delete-documents.ts --university tottori --subject math --exam-type zenki --variant-is-null --dry-run
 *   npx tsx scripts/delete-documents.ts --university tottori --subject math --exam-type zenki --variant-is-null --force
 */

import { createClient } from "@supabase/supabase-js";
import { S3Client, DeleteObjectCommand, HeadObjectCommand } from "@aws-sdk/client-s3";

function getArg(name: string): string | null {
  const idx = process.argv.indexOf(name);
  if (idx >= 0 && process.argv[idx + 1]) return process.argv[idx + 1];
  return null;
}

const idsRaw = getArg("--ids");
const university = getArg("--university");
const subject = getArg("--subject");
const examType = getArg("--exam-type");
const yearFilter = getArg("--year");
const variantIsNull = process.argv.includes("--variant-is-null");
const dryRun = process.argv.includes("--dry-run");
const force = process.argv.includes("--force");
const cascade = process.argv.includes("--cascade");

if (!idsRaw && !university) {
  console.error("Usage: npx tsx scripts/delete-documents.ts (--ids <csv> | --university <id> [--subject <en>] [--exam-type <et>] [--year <n>] [--variant-is-null]) (--dry-run | --force) [--cascade]");
  process.exit(1);
}
if (!dryRun && !force) {
  console.error("Specify --dry-run or --force");
  process.exit(1);
}

const sbUrl = process.env.SUPABASE_URL;
const sbKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
if (!sbUrl || !sbKey) {
  console.error("SUPABASE_URL and SUPABASE_SERVICE_ROLE_KEY are required");
  process.exit(1);
}
const supabase = createClient(sbUrl, sbKey);

const accountId = process.env.R2_ACCOUNT_ID;
const accessKeyId = process.env.R2_ACCESS_KEY_ID;
const secretAccessKey = process.env.R2_SECRET_ACCESS_KEY;
const bucketName = process.env.R2_BUCKET_NAME ?? "kakomon";
if (!accountId || !accessKeyId || !secretAccessKey) {
  console.error("R2_ACCOUNT_ID, R2_ACCESS_KEY_ID, R2_SECRET_ACCESS_KEY are required");
  process.exit(1);
}
const r2 = new S3Client({
  region: "auto",
  endpoint: `https://${accountId}.r2.cloudflarestorage.com`,
  credentials: { accessKeyId, secretAccessKey },
});

async function main() {
  console.log(`Mode: ${dryRun ? "DRY RUN" : "LIVE"}${cascade ? " (cascade)" : ""}\n`);

  // 1. Resolve target records
  let records: any[];

  if (idsRaw) {
    const ids = idsRaw.split(",").map(s => s.trim()).filter(Boolean);
    const { data, error } = await supabase
      .from("kakomon_documents")
      .select("id,year,subject,subject_variant,exam_type,content_type,pdf_storage_path")
      .in("id", ids);
    if (error) { console.error(error); process.exit(1); }
    records = data ?? [];
  } else {
    let query = supabase
      .from("kakomon_documents")
      .select("id,year,subject,subject_variant,exam_type,content_type,pdf_storage_path")
      .eq("university_id", university!)
      .order("year")
      .order("content_type");

    if (subject) query = query.eq("subject", subject);
    if (examType) query = query.eq("exam_type", examType);
    if (yearFilter) query = query.eq("year", parseInt(yearFilter));
    if (variantIsNull) query = query.is("subject_variant", null);

    const { data, error } = await query;
    if (error) { console.error(error); process.exit(1); }
    records = data ?? [];
  }

  if (records.length === 0) {
    console.log("No matching records found.");
    return;
  }

  console.log(`Found ${records.length} records to delete:\n`);
  for (const r of records) {
    const sv = r.subject_variant ? `[${r.subject_variant}]` : "[null]";
    console.log(`  ${r.id.slice(0, 8)} ${r.year} ${r.exam_type.padEnd(6)} ${sv.padEnd(20)} ${r.content_type.padEnd(8)} ${r.pdf_storage_path}`);
  }

  // 2. Check for linked questions
  const ids = records.map((r: any) => r.id);
  const { data: linkedQ, error: qErr } = await supabase
    .from("kakomon_questions")
    .select("id,document_id")
    .in("document_id", ids);
  if (qErr) { console.error(qErr); process.exit(1); }

  if (linkedQ && linkedQ.length > 0) {
    console.log(`\nWARNING: ${linkedQ.length} linked kakomon_questions found.`);
    if (!cascade) {
      console.error("Refusing to delete. Use --cascade to also delete linked questions.");
      process.exit(1);
    }
    console.log("Will delete linked questions (--cascade).");
  }

  if (dryRun) {
    console.log("\n(dry-run: no changes made)");
    return;
  }

  // 3. Delete linked questions if cascade
  if (linkedQ && linkedQ.length > 0 && cascade) {
    console.log("\nDeleting linked questions...");
    for (const q of linkedQ) {
      const { error: dqe } = await supabase.from("kakomon_questions").delete().eq("id", q.id);
      if (dqe) console.error(`  FAILED: ${q.id} - ${dqe.message}`);
    }
    console.log(`  Deleted ${linkedQ.length} questions.`);
  }

  // 4. Delete DB records
  console.log("\nDeleting DB records...");
  let dbOk = 0;
  for (const r of records) {
    const { error: de } = await supabase.from("kakomon_documents").delete().eq("id", r.id);
    if (de) {
      console.error(`  FAILED: ${r.id.slice(0, 8)} - ${de.message}`);
    } else {
      dbOk++;
    }
  }
  console.log(`  DB deleted: ${dbOk}/${records.length}`);

  // 5. Delete R2 objects
  console.log("\nDeleting R2 objects...");
  let r2Ok = 0;
  for (const r of records) {
    try {
      await r2.send(new DeleteObjectCommand({ Bucket: bucketName, Key: r.pdf_storage_path }));
      r2Ok++;
    } catch (err: any) {
      console.error(`  FAILED R2: ${r.pdf_storage_path} - ${err.message}`);
    }
  }
  console.log(`  R2 deleted: ${r2Ok}/${records.length}`);

  console.log(`\nDone: ${dbOk} DB + ${r2Ok} R2 deleted.`);
}

main().catch((err) => { console.error(err); process.exit(1); });

